WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Treatment regimen", "Type of combination"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%renal cell%' AND LOWER("Type of combination") LIKE '%ici+tki%'
)
SELECT * FROM base;
